        0.25 * Math.sin(2 * Math.PI * f * 2 * t) * Math.exp(-t * 6) +
        0.08 * Math.sin(2 * Math.PI * f * 3 * t) * Math.exp(-t * 12)) *
      env *
      amp;
    left[idx] += sig * panL;
    right[idx] += sig * panR;
  }
}

// Warm analog pad chord
