  const start = Math.floor(startSec * SAMPLE_RATE);
  const len = Math.floor(durSec * SAMPLE_RATE);
  const freqs = midis.map(midiToFreq);

  for (let i = 0; i < len; i++) {
    const idx = start + i;
    if (idx >= NUM_SAMPLES) break;
