  // Multi-packet steady stream
  fillRoundRect(ctx, laneX + 34, lane2Y + 145, laneW - 68, 74, 16, "#0B0D12");
  for (let k = 0; k < 4; k++) {
    const u = (localT * 0.35 + k * 0.25) % 1;
