  ctx.font = `500 19px "Geist Mono"`;
  ctx.fillStyle = "#A0AEC0";
  ctx.fillText("Shared monthly quota  ·  One dashboard  ·  One predictable bill", laneX + 34, lane2Y + 275);

  ctx.restore();
}

