  // Thumb handle
  const thumbX = trackX + trackW * sliderPos;
  ctx.save();
  ctx.shadowColor = "rgba(255,51,0,0.35)";
  ctx.shadowBlur = 16;
  ctx.fillStyle = C.white;
  ctx.beginPath();
  ctx.arc(thumbX, trackY, 18, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = C.flare;
