    ctx.save();
    ctx.globalAlpha *= pp;
    drawCard(
      ctx,
      px,
      py,
      pW,
      490,
      24,
      pl.highlight ? C.ink : C.white,
      pl.highlight ? C.flare : C.paperBorder,
