      drawCard(ctx, px - 175, py - 28, 350, 56, 28, C.white, C.paperBorder, 0.06, 10, 24);
      ctx.fillStyle = C.flare;
      ctx.beginPath();
      ctx.arc(px - 140, py, 6, 0, Math.PI * 2);
      ctx.fill();
      ctx.font = `500 20px "Geist"`;
