import("http").then(async ({ createServer }) => {
  const fs = await import("fs");
  const path = await import("path");
  const { chromium } = await import("playwright-core");

  const server = createServer((req, res) => {
    const file = req.url === "/" ? "index.html" : req.url.slice(1);
    const filePath = path.resolve(file);
    if (!fs.existsSync(filePath)) {
      res.writeHead(404);
      return res.end();
    }
    const stat = fs.statSync(filePath);
    const ext = path.extname(filePath);
    const contentType = ext === ".html" ? "text/html" : ext === ".mp4" ? "video/mp4" : "application/octet-stream";
    if (req.headers.range && ext === ".mp4") {
      const [startStr, endStr] = req.headers.range.replace(/bytes=/, "").split("-");
      const start = parseInt(startStr, 10);
      const end = endStr ? parseInt(endStr, 10) : stat.size - 1;
      res.writeHead(206, {
        "Content-Range": `bytes ${start}-${end}/${stat.size}`,
        "Accept-Ranges": "bytes",
        "Content-Length": end - start + 1,
        "Content-Type": contentType,
      });
      fs.createReadStream(filePath, { start, end }).pipe(res);
    } else {
      res.writeHead(200, { "Content-Length": stat.size, "Content-Type": contentType });
      fs.createReadStream(filePath).pipe(res);
    }
  });

  await new Promise(r => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;

  const browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(`http://127.0.0.1:${port}/`);

  const info = await page.evaluate(async () => {
    const v = document.querySelector("video");
    if (v.readyState < 1) {
      await new Promise(r => v.addEventListener("loadedmetadata", r, { once: true }));
    }
    v.muted = true;
    await v.play();
    await new Promise(r => setTimeout(r, 350));
    const rect = v.getBoundingClientRect();
    return {
      title: document.title,
      headings: document.querySelectorAll("h1,h2,h3,h4,h5,h6").length,
      controls: v.controls,
      videoWidth: v.videoWidth,
      videoHeight: v.videoHeight,
      duration: v.duration,
      currentTime: v.currentTime,
      paused: v.paused,
      rect: { width: rect.width, height: rect.height, top: rect.top, left: rect.left },
      viewport: { width: window.innerWidth, height: window.innerHeight }
    };
  });

  console.log(JSON.stringify(info, null, 2));
  await browser.close();
  server.close();
});
'

